const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

/**
 * Cloud masking function for Sentinel-2 L1C images.
 * @param {ee.Image} image The Sentinel-2 image.
 * @return {ee.Image} The cloud-masked image.
 */
function maskS2clouds(image) {
  const qa = image.select('QA60');
  // Bits 10 and 11 are clouds and cirrus, respectively.
  const cloudBitMask = 1 << 10;
  const cirrusBitMask = 1 << 11;
  // Both flags should be set to zero, indicating clear conditions.
  const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
  return image.updateMask(mask).divide(10000); // Scale TOA reflectance to 0-1
}

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const plumePoint = ee.Geometry.Point([-136.275745, 69.264212]);
  const oceanPoint = ee.Geometry.Point([-137.786365, 69.803894]);
  const date = '2017-07-19';

  // Combine geometries for efficient data fetching
  const combinedGeom = ee.Geometry.MultiPoint([plumePoint.coordinates(), oceanPoint.coordinates()]).buffer(10000);

  // 2. Data Acquisition & Check
  let collection = ee.ImageCollection('COPERNICUS/S2')
                      .filterDate(date, ee.Date(date).advance(1, 'day'))
                      .filterBounds(combinedGeom);

  const imageCount = collection.size().getInfo();
  if (imageCount === 0) {
    console.log('No Sentinel-2 images found for the specified date and location.');
    // Fallback attempt to Landsat 8
    collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_TOA')
                   .filterDate(date, ee.Date(date).advance(1, 'day'))
                   .filterBounds(combinedGeom);
    const l8ImageCount = collection.size().getInfo();
    if (l8ImageCount === 0) {
      console.log('Fallback to Landsat 8 also found no images.');
      console.log('A: C1');
      return;
    }
    console.log(`Using Landsat 8 fallback. Images found: ${l8ImageCount}`);
  }

  // 3. Processing
  // Create a cloud-masked mosaic for the day.
  const image = collection.map(maskS2clouds).mosaic();

  // Define a reducer to calculate mean reflectance and count valid pixels.
  // We'll check the average of Red, Green, and Blue bands.
  const reducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  // 4. Calculation
  const plumeStats = image.select(['B4', 'B3', 'B2']).reduceRegion({
    reducer: reducer,
    geometry: plumePoint.buffer(30), // Buffer to get a small area average
    scale: 10,
    maxPixels: 1e9
  });

  const oceanStats = image.select(['B4', 'B3', 'B2']).reduceRegion({
    reducer: reducer,
    geometry: oceanPoint.buffer(30),
    scale: 10,
    maxPixels: 1e9
  });

  const plumeResult = plumeStats.getInfo();
  const oceanResult = oceanStats.getInfo();

  // 5. Validation & Final Answer
  // Check for valid pixels
  const plumePixels = plumeResult['B2_count'];
  const oceanPixels = oceanResult['B2_count'];

  if (plumePixels === 0 || oceanPixels === 0) {
    console.log(`No valid pixels after cloud masking. Plume Pixels: ${plumePixels}, Ocean Pixels: ${oceanPixels}`);
    console.log('A: C2');
    return;
  }

  // Calculate average RGB reflectance
  const plumeAvgReflectance = (plumeResult['B4_mean'] + plumeResult['B3_mean'] + plumeResult['B2_mean']) / 3;
  const oceanAvgReflectance = (oceanResult['B4_mean'] + oceanResult['B3_mean'] + oceanResult['B2_mean']) / 3;

  // Check for calculation failures (nulls or NaNs)
  if (plumeAvgReflectance === null || isNaN(plumeAvgReflectance) || oceanAvgReflectance === null || isNaN(oceanAvgReflectance)) {
    console.log('Calculation failed. One or more results were null or NaN.');
    console.log(`Plume Result: ${plumeAvgReflectance}, Ocean Result: ${oceanAvgReflectance}`);
    console.log('A: C3');
    return;
  }

  console.log(`Plume point (river mouth) mean RGB reflectance: ${plumeAvgReflectance.toFixed(4)}`);
  console.log(`Plume point valid pixels: ${plumePixels}`);
  console.log(`Ocean point mean RGB reflectance: ${oceanAvgReflectance.toFixed(4)}`);
  console.log(`Ocean point valid pixels: ${oceanPixels}`);

  if (plumeAvgReflectance > oceanAvgReflectance) {
    console.log('The plume appears more milky (higher reflectance) than the open ocean.');
    console.log('A: Yes');
  } else {
    console.log('The plume does not appear more milky than the open ocean.');
    console.log('A: No');
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error('An error occurred during initialization or analysis:');
    console.error(e);
    console.log('A: D');
  }
}

initEE();
